import {timeText,can} from './engine.js?v=09c';
import {assignmentEta} from './initial-work.js?v=09c';
export function workboard(s,{header,c,b,ui,esc}){
 header('上一班留下的工作','SHIFT NOTES / EXISTING WORK');const jobs=s.inheritedJobs||[],pending=jobs.filter(j=>j.status==='待安排'),working=jobs.filter(j=>j.status==='處理中');
 c.innerHTML=`<p class="lead">這裡早就在運作，不是從你起床才開始。先分清楚：哪些需要你安排、哪些同事已經在做。<strong>目前 ${pending.length} 件待安排、${working.length} 件處理中。</strong></p>${!jobs.length?'<div class="notice">這份舊進度沒有開局工作清單。重新開始一局，就會依難度帶入前幾班的工作。</div>':''}<div class="workboard-list">${jobs.map(job=>`<article class="inherited-work"><div class="work-status"><span>${esc(job.status)}</span><span>${esc(job.owner)}負責</span><span>${esc(job.priority)}</span>${job.overdue?'<span class="overdue">已超過原訂安排時間</span>':''}</div><h3>${esc(job.title)}</h3><p>${esc(job.progress)}</p><p class="work-next"><strong>下一步：</strong>${esc(job.next)}</p>${job.status==='待安排'?`<p class="work-deadline">希望安排時間：9/${15+(job.deadlineDay??1)} ${timeText(job.deadline)}</p><div class="action-grid">${job.options.map((option,i)=>`<div class="action-item"><button class="secondary" data-action="assignInherited" data-job="${esc(job.id)}" data-choice="${i}" ${can(s,'assignInherited')?'disabled':''}>${esc(option.label)}</button><small>${esc(can(s,'assignInherited')||(option.pending?'物品不交出，下一班繼續追蹤。':`交給${option.actor}，預計 ${timeText(assignmentEta(s,option).due)} 回報。${assignmentEta(s,option).queued?'先做完他手上的工作，再接這件。':''}`))}</small></div>`).join('')}</div>`:job.status==='處理中'?`<p class="work-deadline">預計回報：9/${15+(job.dueDay??1)} ${timeText(job.due)}。不用重派工作。</p>`:''}<button class="quiet" data-open-event="${esc(job.id)}">查看前幾班的紀錄 →</button></article>`).join('')}</div><div class="dialog-actions">${!s.backlogReviewed&&!s.ended?b('我看過了，知道哪些事還在進行','readBacklog','primary'):s.signed?ui('繼續今天的工作','terminal','primary'):ui('回到今天的上班提醒','briefing','primary')}${ui('查看全部事件紀錄','journal')}</div><div class="notice">已完成的歷史檢查也在事件簿。工作分配後會等負責人回報，不會因你按下按鈕就立刻完成。</div>`;
}
